    '            "Type REVISE: followed by your requested changes "\r\n'
    '            "if the report needs improvement."\r\n'
    '        ),\r\n'
    '        provider=review_provider\r\n'
    '    )\r\n'
    '    @listen(or_(writing_crew, revision_crew))\r\n'
    '    def review_draft(self):\r\n'
    '\r\n'
    '        print("\\n[3/5] HUMAN REVIEW")\r\n'
    '        print("Report version:", self.state.revision_count + 1)\r\n'
    '\r\n'
    '        return self.state.draft\r\n'
    '\r\n'
    '\r\n'
    '    # --------------------------------------------------------\r\n'
    '    # STEP 5B: DIRECT PYTHON FEEDBACK ROUTER\r\n'
    '    # --------------------------------------------------------\r\n'
    '\r\n'
    '    @router("review_draft")\r\n'
    '    def route_review(self, result):\r\n'
    '\r\n'
    '        feedback = str(\r\n'
    '            getattr(result, "feedback", "")\r\n'
    '            or ""\r\n'
    '        ).strip()\r\n'
    '\r\n'
    '        normalized = feedback.lower().strip()\r\n'
    '\r\n'
    '        print("\\nREVIEWER DECISION:", feedback)\r\n'
    '\r\n'
    '        # Reject negative approval phrases first\r\n'
    '        negative_phrases = [\r\n'
    '            "do not approve",\r\n'
    '            "don\'t approve",\r\n'
    '            "not approved",\r\n'
    '            "not approve",\r\n'
    '            "needs revision"\r\n'
    '        ]\r\n'
    '\r\n'
    '        if any(\r\n'
    '            phrase in normalized\r\n'
    '            for phrase in negative_phrases\r\n'
    '        ):\r\n'
    '            self.state.feedback = feedback\r\n'
    '            return "revise"\r\n'
    '\r\n'
    '        # Direct approval\r\n'
    '        approval_phrases = [\r\n'
    '            "approve",\r\n'
    '            "approved",\r\n'
    '            "publish",\r\n'
    '            "accept",\r\n'
    '            "looks good"\r\n'
    '        ]\r\n'
    '\r\n'
    '        if any(\r\n'
    '            phrase in normalized\r\n'
    '            for phrase in approval_phrases\r\n'
    '        ):\r\n'
    '            self.state.feedback = ""\r\n'
    '            return "approved"\r\n'
    '\r\n'
    '        # Revision request\r\n'
    '        revision_phrases = [\r\n'
    '            "revise",\r\n'
    '            "revision",\r\n'
    '            "improve",\r\n'
    '            "change",\r\n'
    '            "modify",\r\n'
    '            "update"\r\n'
    '        ]\r\n'
    '\r\n'
    '        if any(\r\n'
    '            phrase in normalized\r\n'
    '            for phrase in revision_phrases\r\n'
    '        ):\r\n'
    '\r\n'
    '            if normalized.startswith("revise"):\r\n'
    '                feedback = re.sub(\r\n'
    '                    r"^revise\\s*:?\\s*",\r\n'
    '                    "",\r\n'
    '                    feedback,\r\n'
    '                    flags=re.IGNORECASE\r\n'
    '                ).strip()\r\n'
    '\r\n'
    '            self.state.feedback = (\r\n'
    '                feedback or "Improve the report."\r\n'
    '            )\r\n'
    '\r\n'
    '            return "revise"\r\n'
    '\r\n'
    '        # Unclear feedback: safely request revision\r\n'
    '        self.state.feedback = (\r\n'
    '            feedback or "Please improve the report."\r\n'
    '        )\r\n'
    '\r\n'
    '        return "revise"\r\n'
    '\r\n'
    '\r\n'
    '# ============================================================\r\n'
    '# 7. START APPROVAL REPORT FLOW\r\n'
    '# ============================================================\r\n'
    '\r\n'
    'def run_approval_report(topic: str, audience: str):\r\n'
    '\r\n'
    '    if not topic or not topic.strip():\r\n'
    '        raise ValueError("Report topic cannot be empty.")\r\n'
    '\r\n'
    '    flow = ApprovalReportFlow()\r\n'
    '\r\n'
    '    flow.state.topic = topic.strip()\r\n'
    '\r\n'
    '    flow.state.audience = (\r\n'
    '        audience.strip()\r\n'
    '        if audience and audience.strip()\r\n'
    '        else "General audience"\r\n'
    '    )\r\n'
    '\r\n'
    '    result = flow.kickoff()\r\n'
    '\r\n'
    '    if isinstance(result, HumanFeedbackPending):\r\n'
    '\r\n'
    '        return {\r\n'
    '            "status": "pending_review",\r\n'
    '            "flow_id": result.context.flow_id,\r\n'
    '            "topic": flow.state.topic,\r\n'
    '            "audience": flow.state.audience,\r\n'
    '            "draft": result.context.method_output,\r\n'
    '            "revision_count": flow.state.revision_count,\r\n'
    '            "message": (\r\n'
    '                "Report generated. Review it and submit "\r\n'
    '                "APPROVE or REVISE through /agent10/review."\r\n'
    '            )\r\n'
    '        }\r\n'
    '\r\n'
    '    return {\r\n'
    '        "status": flow.state.status,\r\n'
    '        "topic": flow.state.topic,\r\n'
    '        "audience": flow.state.audience,\r\n'
    '        "revision_count": flow.state.revision_count,\r\n'
    '        "report_file": flow.state.report_file\r\n'
    '    }\r\n'
    '\r\n'
    '\r\n'
    '# ============================================================\r\n'
    '# 8. RESUME APPROVAL FLOW\r\n'
    '# ============================================================\r\n'
    '\r\n'
    'def review_approval_report(flow_id: str, feedback: str):\r\n'
    '\r\n'
    '    if not flow_id or not flow_id.strip():\r\n'
    '        raise ValueError("Flow ID cannot be empty.")\r\n'
    '\r\n'
    '    if not feedback or not feedback.strip():\r\n'
    '        raise ValueError("Review feedback cannot be empty.")\r\n'
    '\r\n'
    '    flow = ApprovalReportFlow.from_pending(\r\n'
    '        flow_id.strip()\r\n'
    '    )\r\n'
    '\r\n'
    '    result = flow.resume(feedback.strip())\r\n'
    '\r\n'
    '    if isinstance(result, HumanFeedbackPending):\r\n'
    '\r\n'
    '        return {\r\n'
    '            "status": "pending_review",\r\n'
    '            "flow_id": result.context.flow_id,\r\n'
    '            "topic": flow.state.topic,\r\n'
    '            "audience": flow.state.audience,\r\n'
    '            "draft": result.context.method_output,\r\n'
    '            "revision_count": flow.state.revision_count,\r\n'
    '            "message": (\r\n'
    '                "The report has been revised. Please review "\r\n'
    '                "the new draft and submit your decision again."\r\n'
    '            )\r\n'
    '        }\r\n'
    '\r\n'
    '    return {\r\n'
    '        "status": flow.state.status,\r\n'
    '        "topic": flow.state.topic,\r\n'
    '        "audience": flow.state.audience,\r\n'
    '        "revision_count": flow.state.revision_count,\r\n'
    '        "report_file": flow.state.report_file,\r\n'
    '        "message": (\r\n'
