# ----- Original source: projects/blog_post.py -----
PROJECT_SOURCES['blog_post.py'] = (
    '\r\n'
    'import os\r\n'
    'from crewai import Agent, Task, Crew, Process, LLM\r\n'
    'from ddgs import DDGS\r\n'
    '\r\n'
    '\r\n'
    '\r\n'
    'def run_blog_post(topic: str):\r\n'
    '\r\n'
    '    # 1. Configure Gemini\r\n'
    '    api_key = os.getenv("GEMINI_API_KEY")\r\n'
    '\r\n'
    '    if not api_key:\r\n'
    '        raise ValueError("GEMINI_API_KEY is not configured.")\r\n'
    '\r\n'
    '    llm = LLM(\r\n'
    '        model="gemini/gemini-3.1-flash-lite-preview",\r\n'
    '        api_key=api_key,\r\n'
    '        temperature=0.4\r\n'
    '    )\r\n'
    '\r\n'
    '    # 2. Search the web\r\n'
    '    def search_web(topic):\r\n'
    '        results = DDGS().text(topic, max_results=5)\r\n'
    '        research = []\r\n'
    '\r\n'
    '        for item in results:\r\n'
    '            research.append(\r\n'
    '                f"Title: {item.get(\'title\', \'\')}\\n"\r\n'
    '                f"Description: {item.get(\'body\', \'\')}\\n"\r\n'
    '                f"URL: {item.get(\'href\', \'\')}"\r\n'
    '            )\r\n'
    '\r\n'
    '        return "\\n\\n".join(research)\r\n'
    '\r\n'
    '    try:\r\n'
    '        research_data = search_web(topic)\r\n'
    '    except Exception as e:\r\n'
    '        print("Search failed:", e)\r\n'
    '        research_data = (\r\n'
    '            "No web search results available. "\r\n'
    '            "Avoid unsupported factual claims."\r\n'
    '        )\r\n'
    '\r\n'
    '    # 3. Create agents\r\n'
    '    researcher = Agent(\r\n'
    '        role="Researcher",\r\n'
    '        goal="Analyze search results and identify useful facts",\r\n'
    '        backstory="You are a careful web researcher.",\r\n'
    '        llm=llm,\r\n'
    '        verbose=True\r\n'
    '    )\r\n'
    '\r\n'
    '    writer = Agent(\r\n'
    '        role="Blog Writer",\r\n'
    '        goal="Write an engaging blog post of approximately 600 words",\r\n'
    '        backstory="You write clear, informative blog posts.",\r\n'
    '        llm=llm,\r\n'
    '        verbose=True\r\n'
    '    )\r\n'
    '\r\n'
    '    editor = Agent(\r\n'
    '        role="Editor",\r\n'
    '        goal="Polish the blog post and check factual consistency",\r\n'
    '        backstory="You are an experienced editor.",\r\n'
    '        llm=llm,\r\n'
    '        verbose=True\r\n'
    '    )\r\n'
    '\r\n'
    '    # 4. Create tasks\r\n'
    '    research_task = Task(\r\n'
    '        description=f"""\r\n'
    '        Research topic: {topic}\r\n'
    '\r\n'
    '        Analyze these DDGS search results:\r\n'
    '        {research_data}\r\n'
    '\r\n'
    '        Identify key facts, benefits, challenges and examples.\r\n'
    '        Keep source URLs and do not invent facts.\r\n'
    '        """,\r\n'
    '        expected_output="Research notes with facts and source URLs.",\r\n'
    '        agent=researcher\r\n'
    '    )\r\n'
    '\r\n'
    '    writing_task = Task(\r\n'
    '        description=f"""\r\n'
    '        Write a blog post about {topic} using the research.\r\n'
    '\r\n'
    '        Include a title, introduction, headings, examples,\r\n'
    '        benefits, challenges and conclusion.\r\n'
    '\r\n'
    '        Write approximately 600 words in Markdown.\r\n'
    '        Preserve relevant source URLs.\r\n'
    '        """,\r\n'
    '        expected_output="A complete Markdown blog post.",\r\n'
    '        agent=writer,\r\n'
    '        context=[research_task]\r\n'
    '    )\r\n'
    '\r\n'
    '    editing_task = Task(\r\n'
    '        description="""\r\n'
    '        Edit the blog post for grammar, clarity, structure\r\n'
    '        and factual consistency.\r\n'
    '\r\n'
    '        Preserve useful source URLs.\r\n'
    '        Return only the final polished blog post in Markdown.\r\n'
    '        """,\r\n'
    '        expected_output="A polished final blog post in Markdown.",\r\n'
    '        agent=editor,\r\n'
    '        context=[research_task, writing_task]\r\n'
    '    )\r\n'
    '\r\n'
    '    # 5. Create Crew\r\n'
    '    blog_crew = Crew(\r\n'
    '        agents=[researcher, writer, editor],\r\n'
    '        tasks=[research_task, writing_task, editing_task],\r\n'
    '        process=Process.sequential,\r\n'
    '        verbose=True\r\n'
    '    )\r\n'
    '\r\n'
    '    # 6. Run Crew\r\n'
    '    result = blog_crew.kickoff()\r\n'
    '\r\n'
    '    # 7. Return output to FastAPI\r\n'
    '    return str(result)\r\n'
    '\r\n'
    '\r\n'
    'def agent1(data: dict):\r\n'
    '    topic = data.get("input")\r\n'
    '\r\n'
    '    if not topic:\r\n'
    '        return {"error": "Please provide a blog topic"}\r\n'
    '\r\n'
    '    result = run_blog_post(topic)\r\n'
    '\r\n'
    '    return {"output": result}'
)

