@app.get(
    "/health",
    tags=["Health"],
    summary="Health & Performance Dashboard"
)
def health_check():

    agents = {}

    for project, function_name in EXPECTED_AGENTS.items():

        namespace = PROJECTS.get(project, {})
        loaded = callable(namespace.get(function_name))

        stats = AGENT_METRICS.get(project, {})

        calls = stats.get("calls", 0)
        total_time = stats.get("total_duration_ms", 0)

        agents[project] = {
            "status": "Ready" if loaded else "Not Loaded",
            "function": function_name,
            "total_calls": calls,
            "successful_calls": stats.get("success", 0),
            "failed_calls": stats.get("failures", 0),
            "average_response_time_ms": (
                round(total_time / calls, 2) if calls else 0
            ),
            "last_response_time_ms": stats.get("last_duration_ms"),
            "last_status": stats.get("last_status", "Not Run")
        }

    ready_count = sum(
        1 for agent in agents.values()
        if agent["status"] == "Ready"
    )

    return {
        "overall_status": (
            "Healthy" if ready_count == 10 else "Degraded"
        ),
        "total_agents": 10,
        "ready_agents": ready_count,
        "not_loaded_agents": 10 - ready_count,
        "agents": agents
    }

